using T16R64             = Nvfp4A4MmaSchedule<16, 64, 256, 1, 4, 2, 2>;
using T32R64             = Nvfp4A4MmaSchedule<32, 64, 256, 2, 4, 2, 2>;
using T32R128            = Nvfp4A4MmaSchedule<32, 128, 256, 2, 4, 2, 1>;
